export const leads = pgTable("leads", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	unit: text().default('IQWM').notNull(),
	name: text().notNull(),
	phone: text(),
	email: text(),
	city: text(),
	age: integer(),
	maritalStatus: text("marital_status"),
	incomeBand: text("income_band"),
	language: text(),
	requirement: text(),
	budget: text(),
	product: text().notNull(),
	source: text().notNull(),
	campaign: text(),
	referredBy: text("referred_by"),
	bucket: leadBucket().default('active_contact').notNull(),
	strikes: integer().default(0).notNull(),
	nextFollowUp: date("next_follow_up"),
	meetingAt: timestamp("meeting_at", { withTimezone: true, mode: 'string' }),
	deferredUntil: date("deferred_until"),
	outReason: text("out_reason"),
	outFromBucket: leadBucket("out_from_bucket"),
	outAt: timestamp("out_at", { withTimezone: true, mode: 'string' }),
	convertedAt: timestamp("converted_at", { withTimezone: true, mode: 'string' }),
	lastContactAt: timestamp("last_contact_at", { withTimezone: true, mode: 'string' }),
	rmId: uuid("rm_id").notNull(),
	importBatchId: uuid("import_batch_id"),
	createdBy: uuid("created_by"),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	meetingUrl: text("meeting_url"),
	holdingStep: integer("holding_step").default(0).notNull(),
}, (table) => [
	index("leads_follow_up_idx").using("btree", table.nextFollowUp.asc().nullsLast().op("date_ops")).where(sql`(bucket <> ALL (ARRAY['out'::lead_bucket, 'converting'::lead_bucket]))`),
	index("leads_name_trgm").using("gin", table.name.asc().nullsLast().op("gin_trgm_ops")),
	index("leads_rm_bucket_idx").using("btree", table.rmId.asc().nullsLast().op("enum_ops"), table.bucket.asc().nullsLast().op("uuid_ops")),
	uniqueIndex("leads_unit_email_uq").using("btree", table.unit.asc().nullsLast().op("text_ops"), table.email.asc().nullsLast().op("text_ops")).where(sql`(email IS NOT NULL)`),
	uniqueIndex("leads_unit_phone_uq").using("btree", table.unit.asc().nullsLast().op("text_ops"), table.phone.asc().nullsLast().op("text_ops")).where(sql`(phone IS NOT NULL)`),
	foreignKey({
			columns: [table.unit],
			foreignColumns: [businessUnits.code],
			name: "leads_unit_fkey"
		}),
	foreignKey({
			columns: [table.source],
			foreignColumns: [leadSources.name],
			name: "leads_source_fkey"
		}).onUpdate("cascade"),
	foreignKey({
			columns: [table.rmId],
			foreignColumns: [profiles.id],
			name: "leads_rm_id_fkey"
		}),
	foreignKey({
			columns: [table.importBatchId],
			foreignColumns: [importBatches.id],
			name: "leads_import_batch_id_fkey"
		}).onDelete("set null"),
	foreignKey({
			columns: [table.createdBy],
			foreignColumns: [profiles.id],
			name: "leads_created_by_fkey"
		}),
	pgPolicy("leads_read", { as: "permissive", for: "select", to: ["authenticated"], using: sql`(is_admin() OR (rm_id = auth.uid()))` }),
	check("leads_name_check", sql`length(TRIM(BOTH FROM name)) > 0`),
	check("leads_age_check", sql`(age IS NULL) OR ((age >= 16) AND (age <= 110))`),
	check("leads_strikes_check", sql`(strikes >= 0) AND (strikes <= 5)`),
	check("leads_check", sql`(phone IS NOT NULL) OR (email IS NOT NULL)`),
	check("leads_product_check", sql`product = ANY (ARRAY['RIA'::text, 'PMS'::text, 'US RIA'::text])`),
]);

export const gmailMessages = pgTable("gmail_messages", {
	messageId: text("message_id").notNull(),
	userId: uuid("user_id").notNull(),
	leadId: uuid("lead_id").notNull(),
	threadId: text("thread_id"),
	direction: text().notNull(),
	subject: text(),
	sentAt: timestamp("sent_at", { withTimezone: true, mode: 'string' }).notNull(),
}, (table) => [
	index("gmail_messages_lead_idx").using("btree", table.leadId.asc().nullsLast().op("timestamptz_ops"), table.sentAt.desc().nullsFirst().op("uuid_ops")),
	foreignKey({
			columns: [table.userId],
			foreignColumns: [profiles.id],
			name: "gmail_messages_user_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.leadId],
			foreignColumns: [leads.id],
			name: "gmail_messages_lead_id_fkey"
		}).onDelete("cascade"),
	primaryKey({ columns: [table.messageId, table.userId], name: "gmail_messages_pkey"}),
	pgPolicy("gmail_messages_read", { as: "permissive", for: "select", to: ["authenticated"], using: sql`((user_id = auth.uid()) OR can_access_lead(lead_id))` }),
	check("gmail_messages_direction_check", sql`direction = ANY (ARRAY['in'::text, 'out'::text])`),
]);
